  'district.park.tokenName':'listones de papalote que se llevó el viento',
  'life.findLabel.beach':'Estrellita de mar, recógela',
  'life.findLabel.park':'Listón de papalote perdido, recógelo',
  'daily.item.beach.0':'una visera de repuesto',
  'daily.item.beach.1':'un frasco de bloqueador solar',
  'daily.item.beach.2':'un llavero de dólar de arena',
